def merge(*dicts, **kwargs):
    """ Merge a collection of dictionaries or Mappings

    >>> merge({1: 'one'}, {2: 'two'})
    {1: 'one', 2: 'two'}

    Later dictionaries have precedence

    >>> merge({1: 2, 3: 4}, {3: 3, 4: 4})
    {1: 2, 3: 3, 4: 4}

    Works with any Mapping type, returning the same type as the first argument.

    >>> from collections import OrderedDict
    >>> merge(OrderedDict([(1, 'one')]), {2: 'two'})
    OrderedDict([(1, 'one'), (2, 'two')])

    See Also:
        merge_with
    """
    if len(dicts) == 1 and not isinstance(dicts[0], dict):
        dicts = dicts[0]

    # Determine factory from first argument or kwargs
    factory = kwargs.pop('factory', None)
    if factory is None and dicts:
        # Try to get first element without consuming iterator
        try:
            first = dicts[0]
            if isinstance(first, Mapping):
                factory = type(first)
            else:
                factory = dict
        except (TypeError, IndexError):
            # Not subscriptable (e.g., iterator), use default
            factory = dict

    if factory is None:
        factory = dict

    rv = factory()
    for d in dicts:
        rv.update(d)
    return rv
